// Medieval & early modern world, 500–1799 CE. Every claim checked against the cited pages.
TL.add({
  branches: [
    { id: "islam", name: "Islam", region: "faiths",
      start: 610, end: null, startWhen: "c. 610", endWhen: "",
      parents: [], into: [],
      text: "Monotheistic faith founded by Muhammad, who at about 40, c. 610, reported being visited by the angel Gabriel in a cave; Muslims regard him as the final prophet of God.",
      cites: [{ t: "Muhammad — Wikipedia", u: "https://en.wikipedia.org/wiki/Muhammad" }] },
    { id: "rashidun", name: "Rashidun Caliphate", region: "mideast",
      start: 632, end: 661, startWhen: "632", endWhen: "661",
      parents: ["islam"], into: ["umayyad"],
      text: "Rule of the four “Rightly Guided” caliphs (Abu Bakr, Umar, Uthman, Ali) after Muhammad's death. They took Egypt by 642 and finished conquering Persia in 651; civil war ended with Mu'awiya founding the Umayyad Caliphate in 661.",
      cites: [{ t: "Rashidun Caliphate — Wikipedia", u: "https://en.wikipedia.org/wiki/Rashidun_Caliphate" }] },
    { id: "umayyad", name: "Umayyad Caliphate", region: "mideast",
      start: 661, end: 750, startWhen: "661", endWhen: "750",
      parents: ["rashidun"], into: ["abbasid"],
      text: "Caliphate ruled by the Umayyad dynasty from Damascus, 661–750, covering 11–15 million km² at its height. The Abbasids overthrew Marwan II in 750; a surviving Umayyad, Abd al-Rahman I, set up an independent state at Córdoba.",
      cites: [{ t: "Umayyad Caliphate — Wikipedia", u: "https://en.wikipedia.org/wiki/Umayyad_Caliphate" }] },
    { id: "abbasid", name: "Abbasid Caliphate", region: "mideast",
      start: 750, end: 1258, startWhen: "750", endWhen: "1258 (symbolic caliphate in Cairo to 1517)",
      parents: ["umayyad"], into: [],
      text: "Dynasty that overthrew the Umayyads and ruled from Iraq, mostly from Baghdad, until the Mongol sack of 1258; Baghdad's House of Wisdom helped usher in the Islamic Golden Age. Abbasids kept symbolic authority in Cairo until 1517.",
      cites: [{ t: "Abbasid Caliphate — Wikipedia", u: "https://en.wikipedia.org/wiki/Abbasid_Caliphate" }] },
    { id: "al-andalus", name: "al-Andalus", region: "europe",
      start: 711, end: 1492, startWhen: "711", endWhen: "January 2, 1492",
      parents: ["umayyad"], into: ["spain"],
      text: "Muslim-ruled territories of Iberia, 711–1492: Umayyad emirate (756), Caliphate of Córdoba (929–1031), then taifa states. A conduit for exchange between the Islamic and Christian worlds, it ended when Granada surrendered in 1492.",
      cites: [{ t: "Al-Andalus — Wikipedia", u: "https://en.wikipedia.org/wiki/Al-Andalus" }] },
    { id: "catholicism", name: "Catholic Church (Latin West)", region: "faiths",
      start: 1054, end: null, startWhen: "1054", endWhen: "",
      parents: ["christianity"], into: [],
      text: "The Latin church in communion with the bishop of Rome (the pope), the largest Christian denomination. Its break with the Eastern churches, sealed by mutual excommunications in 1054, was solidified by the Fourth Crusade.",
      cites: [{ t: "Catholic Church — Wikipedia", u: "https://en.wikipedia.org/wiki/Catholic_Church" },
              { t: "East–West Schism — Wikipedia", u: "https://en.wikipedia.org/wiki/East%E2%80%93West_Schism" }] },
    { id: "orthodoxy", name: "Eastern Orthodox Church", region: "faiths",
      start: 1054, end: null, startWhen: "1054", endWhen: "",
      parents: ["christianity"], into: [],
      text: "Communion of self-governing (autocephalous) churches, with the Patriarch of Constantinople as first among equals; the second-largest Christian body. The 1054 schism with Rome culminated disputes centered on papal authority.",
      cites: [{ t: "Eastern Orthodox Church — Wikipedia", u: "https://en.wikipedia.org/wiki/Eastern_Orthodox_Church" }] },
    { id: "protestantism", name: "Protestantism", region: "faiths",
      start: 1517, end: null, startWhen: "October 31, 1517 (conventional)", endWhen: "",
      parents: ["catholicism"], into: [],
      text: "Branch of Western Christianity born in the 16th-century Reformation, which challenged the papacy and Catholic hierarchy; Luther's Ninety-five Theses (1517) is the usual start, and Calvin developed the Reformed tradition.",
      cites: [{ t: "Reformation — Wikipedia", u: "https://en.wikipedia.org/wiki/Reformation" }] },
    { id: "ottoman", name: "Ottoman Empire", region: "mideast",
      start: 1299, end: 1922, startWhen: "c. 1299", endWhen: "1922",
      parents: [], into: ["turkey"],
      text: "Empire founded c. 1299 in northwestern Anatolia by Osman I. It took Constantinople in 1453 and became a global power under Suleiman the Magnificent; the sultanate ended in 1922, and the Republic of Turkey followed in 1923.",
      cites: [{ t: "Ottoman Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Ottoman_Empire" }] },
    { id: "ilkhanate", name: "Ilkhanate", region: "mideast",
      start: 1256, end: 1335, startWhen: "1256", endWhen: "1335",
      parents: ["mongol-empire"], into: [],
      text: "Mongol khanate in the empire's southwest, founded by Genghis Khan's grandson Hülegü, who destroyed the Abbasid Caliphate in 1258. Its rulers converted to Islam from Ghazan (1295); it fell apart after Abu Sa'id died in 1335.",
      cites: [{ t: "Ilkhanate — Wikipedia", u: "https://en.wikipedia.org/wiki/Ilkhanate" }] },
    { id: "safavid", name: "Safavid Iran", region: "mideast",
      start: 1501, end: 1736, startWhen: "December 22, 1501", endWhen: "1736 (some date the fall to 1722)",
      parents: [], into: [],
      text: "Iranian empire of the Safavid dynasty, 1501–1736. Shah Ismail I made Twelver Shi'ism the official religion; Isfahan was capital from 1598. Isfahan fell to Afghans in 1722, and Nader Shah's coronation in 1736 ended the dynasty.",
      cites: [{ t: "Safavid Iran — Wikipedia", u: "https://en.wikipedia.org/wiki/Safavid_Iran" }] },
    { id: "franks", name: "Frankish kingdoms (Francia)", region: "europe",
      start: 481, end: 843, startWhen: "481", endWhen: "843",
      parents: ["western-roman"], into: ["west-francia", "east-francia"],
      text: "Largest post-Roman kingdom in Western Europe, ruled by Merovingians then Carolingians. Clovis I unified the Franks in 481 and most of Gaul after Roman rule collapsed; the Treaty of Verdun (843) split it into three.",
      cites: [{ t: "Francia — Wikipedia", u: "https://en.wikipedia.org/wiki/Francia" }] },
    { id: "west-francia", name: "West Francia", region: "europe",
      start: 843, end: 987, startWhen: "August 843", endWhen: "987",
      parents: ["franks"], into: ["france"],
      text: "Western share of the Carolingian empire, given to Charles the Bald at Verdun in 843. Norsemen settled Normandy after 911; the election of Hugh Capet in 987 began the Capetian dynasty and the transition to the Kingdom of France.",
      cites: [{ t: "West Francia — Wikipedia", u: "https://en.wikipedia.org/wiki/West_Francia" }] },
    { id: "france", name: "France", region: "europe",
      start: 987, end: null, startWhen: "987", endWhen: "",
      parents: ["west-francia"], into: [],
      text: "Kingdom whose Capetian line began with Hugh Capet's accession in 987. It fought England in the Hundred Years' War (1337–1453) and was ruled by Louis XIV from 1643 to 1715; the Revolution of 1789 led to the monarchy's abolition in 1792.",
      cites: [{ t: "Kingdom of France — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_France" }] },
    { id: "east-francia", name: "East Francia", region: "europe",
      start: 843, end: 962, startWhen: "843", endWhen: "962",
      parents: ["franks"], into: ["hre"],
      text: "Eastern, mostly Germanic-speaking share of the Carolingian empire, given to Louis the German in 843. Kingship passed to the Saxon Ottonians in 919; Otto I's imperial coronation in Rome (962) began the Holy Roman Empire.",
      cites: [{ t: "East Francia — Wikipedia", u: "https://en.wikipedia.org/wiki/East_Francia" }] },
    { id: "hre", name: "Holy Roman Empire", region: "europe",
      start: 962, end: 1806, startWhen: "962 (some date it from 800)", endWhen: "August 6, 1806",
      parents: ["east-francia"], into: ["german-confederation"],
      text: "Central European empire dated from either Charlemagne's coronation (800) or Otto I's (962). Emperor Francis II dissolved it on August 6, 1806; after 1815 most of its lands joined the German Confederation.",
      cites: [{ t: "Holy Roman Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Holy_Roman_Empire" }] },
    { id: "england", name: "Kingdom of England", region: "europe",
      start: 927, end: 1707, startWhen: "927", endWhen: "May 1, 1707",
      parents: [], into: ["great-britain"],
      text: "Kingdom unified when Æthelstan took York, the last Viking-held kingdom, in 927. Conquered by the Normans in 1066, it shared a monarch with Scotland from 1603 and merged with it as Great Britain in 1707.",
      cites: [{ t: "Kingdom of England — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_England" }] },
    { id: "scotland", name: "Kingdom of Scotland", region: "europe",
      start: 843, end: 1707, startWhen: "843 (traditional)", endWhen: "May 1, 1707",
      parents: [], into: ["great-britain"],
      text: "Kingdom traditionally founded in 843 by Kenneth MacAlpin from a merger of Gaelic and Pictish kingdoms. It kept its independence in the wars with England (1296–1357) and joined England as Great Britain on May 1, 1707.",
      cites: [{ t: "Kingdom of Scotland — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Scotland" }] },
    { id: "great-britain", name: "Kingdom of Great Britain", region: "europe",
      start: 1707, end: 1801, startWhen: "May 1, 1707", endWhen: "January 1, 1801",
      parents: ["england", "scotland"], into: ["uk"],
      text: "State created when the Acts of Union joined England and Scotland under one parliament at Westminster. It lost the Thirteen Colonies in the American Revolutionary War and merged with Ireland into the United Kingdom on January 1, 1801.",
      cites: [{ t: "Kingdom of Great Britain — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Great_Britain" }] },
    { id: "castile", name: "Crown of Castile", region: "europe",
      start: 1230, end: 1479, startWhen: "1230", endWhen: "1479 (dynastic union with Aragon)",
      parents: [], into: ["spain"],
      text: "Polity formed in 1230 by the final union of Castile and León under Ferdinand III, which took Córdoba (1236) and Seville (1248). Isabella I's marriage to Ferdinand of Aragon led to a dynastic union of the two crowns in 1479.",
      cites: [{ t: "Crown of Castile — Wikipedia", u: "https://en.wikipedia.org/wiki/Crown_of_Castile" }] },
    { id: "aragon", name: "Crown of Aragon", region: "europe",
      start: 1137, end: 1479, startWhen: "1137", endWhen: "1479 (dynastic union; abolished 1707–1716)",
      parents: [], into: ["spain"],
      text: "Born in 1137 from the dynastic union of Aragon and the County of Barcelona, it grew into a Mediterranean empire with Sardinia, Sicily and Naples. United dynastically with Castile in 1479; the Nueva Planta decrees abolished it.",
      cites: [{ t: "Crown of Aragon — Wikipedia", u: "https://en.wikipedia.org/wiki/Crown_of_Aragon" }] },
    { id: "spain", name: "Spain", region: "europe",
      start: 1479, end: null, startWhen: "1479", endWhen: "",
      parents: ["castile", "aragon"], into: [],
      text: "Composite monarchy built on the 1479 dynastic union of Castile and Aragon. From Columbus's 1492 voyage it built an empire in the Americas and, from 1565, the Philippines; the Nueva Planta decrees (1707–1716) unified its crowns.",
      cites: [{ t: "Crown of Aragon — Wikipedia", u: "https://en.wikipedia.org/wiki/Crown_of_Aragon" },
              { t: "Crown of Castile — Wikipedia", u: "https://en.wikipedia.org/wiki/Crown_of_Castile" },
              { t: "Spanish Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Spanish_Empire" }] },
    { id: "portugal", name: "Portugal", region: "europe",
      start: 1139, end: null, startWhen: "July 26, 1139 (acclamation; recognized 1143, 1179)", endWhen: "",
      parents: [], into: [],
      text: "Kingdom from Afonso Henriques' acclamation in 1139, recognized by León-Castile in 1143 and the pope in 1179. Its 15th–16th-century exploration built a vast colonial empire; it was in personal union with Spain 1580–1640.",
      cites: [{ t: "Kingdom of Portugal — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Portugal" }] },
    { id: "kievan-rus", name: "Kievan Rus'", region: "europe",
      start: 882, end: 1240, startWhen: "882 (per the Primary Chronicle)", endWhen: "1240",
      parents: [], into: [],
      text: "East Slavic state ruled by the Rurik dynasty, said to descend from the Varangian prince Rurik; the chronicle has Oleg take Kiev in 882. It peaked under Yaroslav the Wise and fell to the Mongols, Kiev being besieged in 1240.",
      cites: [{ t: "Kievan Rus' — Wikipedia", u: "https://en.wikipedia.org/wiki/Kievan_Rus%27" }] },
    { id: "golden-horde", name: "Golden Horde", region: "europe",
      start: 1225, end: 1502, startWhen: "c. 1225 (Batu reigned from 1242)", endWhen: "1502",
      parents: ["mongol-empire"], into: [],
      text: "Mongol, later Turkicized, khanate built on Jochi's share of the empire and greatly enlarged by Batu. It adopted Islam under Özbeg Khan (1312–1341); after the Crimean Khanate sacked Sarai in 1502, successor khanates remained.",
      cites: [{ t: "Golden Horde — Wikipedia", u: "https://en.wikipedia.org/wiki/Golden_Horde" }] },
    { id: "muscovy", name: "Grand Duchy of Moscow", region: "europe",
      start: 1263, end: 1547, startWhen: "1263", endWhen: "1547",
      parents: [], into: ["tsardom-russia"],
      text: "Principality that split from Vladimir-Suzdal when Daniel received Moscow (r. 1263–1303). Under Mongol suzerainty, it beat the Tatars at Kulikovo (1380); Ivan IV's coronation as tsar in 1547 created the Tsardom of Russia.",
      cites: [{ t: "Grand Duchy of Moscow — Wikipedia", u: "https://en.wikipedia.org/wiki/Grand_Duchy_of_Moscow" }] },
    { id: "tsardom-russia", name: "Tsardom of Russia", region: "europe",
      start: 1547, end: 1721, startWhen: "January 16, 1547", endWhen: "1721",
      parents: ["muscovy"], into: ["russian-empire"],
      text: "Russian state from Ivan IV's coronation as tsar (1547). It annexed Kazan in 1552 and pushed into Siberia; after the Time of Troubles the Romanovs took the throne in 1613. Peter the Great proclaimed the Russian Empire in 1721.",
      cites: [{ t: "Tsardom of Russia — Wikipedia", u: "https://en.wikipedia.org/wiki/Tsardom_of_Russia" }] },
    { id: "russian-empire", name: "Russian Empire", region: "europe",
      start: 1721, end: 1917, startWhen: "1721", endWhen: "1917",
      parents: ["tsardom-russia"], into: [],
      text: "Empire proclaimed by Peter the Great in 1721, with St Petersburg (founded 1703) as capital. It expanded under Catherine the Great (1762–1796), absorbed most of partitioned Poland, and ended in the 1917 revolutions.",
      cites: [{ t: "Russian Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Russian_Empire" }] },
    { id: "ghana-empire", name: "Ghana Empire (Wagadu)", region: "africa",
      start: 300, end: 1250, startWhen: "c. 300", endWhen: "mid-13th century",
      parents: [], into: ["mali"],
      text: "Soninke-led West African empire enriched by trans-Saharan gold and salt trade; its likely later capital was Koumbi Saleh. The Sosso conquered it by 1203; it then became a vassal of Mali. A claimed Almoravid conquest of 1076 is disputed.",
      cites: [{ t: "Ghana Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Ghana_Empire" }] },
    { id: "mali", name: "Mali Empire", region: "africa",
      start: 1235, end: 1610, startWhen: "c. 1235", endWhen: "c. 1610",
      parents: [], into: [],
      text: "Mande empire founded by Sundiata Keita after the Battle of Kirina (c. 1235). Mansa Musa annexed Timbuktu in 1324; Songhai took its lands from the 15th century, and it ended after Mahmud Keita IV's death (c. 1610).",
      cites: [{ t: "Mali Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Mali_Empire" }] },
    { id: "songhai", name: "Songhai Empire", region: "africa",
      start: 1464, end: 1591, startWhen: "1464 (Sonni Ali's accession)", endWhen: "1591",
      parents: ["mali"], into: [],
      text: "Empire centered on Gao. Once subject to Mali, Songhai expanded under Sonni Ali (r. 1464–1492), taking Timbuktu in 1468, and was reformed by Askia Muhammad; it collapsed after Morocco's victory at Tondibi in 1591.",
      cites: [{ t: "Songhai Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Songhai_Empire" }] },
    { id: "great-zimbabwe", name: "Kingdom of Zimbabwe", region: "africa",
      start: 1220, end: 1450, startWhen: "13th century", endWhen: "c. 1450 (site inhabited into the 17th century)",
      parents: [], into: [],
      text: "Shona kingdom whose capital, Great Zimbabwe, is the largest stone structure in precolonial southern Africa. From c. 1300 it exported gold via Swahili city-states; Persian and Chinese wares reached it. Power shifted to Mutapa and Butua.",
      cites: [{ t: "Kingdom of Zimbabwe — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Zimbabwe" }] },
    { id: "ethiopia", name: "Ethiopian Empire", region: "africa",
      start: 1270, end: 1974, startWhen: "1270", endWhen: "1974",
      parents: [], into: [],
      text: "Solomonic-dynasty empire founded when Yekuno Amlak replaced the Zagwe in 1270, claiming descent from Aksum's kings and Solomon. Gondar's 1630s founding began a golden age; the 1974 Derg coup ended Haile Selassie's reign.",
      cites: [{ t: "Ethiopian Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Ethiopian_Empire" }] },
    { id: "delhi-sultanate", name: "Delhi Sultanate", region: "southasia",
      start: 1206, end: 1526, startWhen: "1206", endWhen: "1526",
      parents: [], into: ["mughal"],
      text: "Delhi-based empire set up in 1206 by Qutb ud-Din Aibak in former Ghurid lands, ruled by five dynasties. It fended off Mongol invasions and fostered Indo-Islamic architecture; Babur's victory at Panipat in 1526 ended it.",
      cites: [{ t: "Delhi Sultanate — Wikipedia", u: "https://en.wikipedia.org/wiki/Delhi_Sultanate" }] },
    { id: "mughal", name: "Mughal Empire", region: "southasia",
      start: 1526, end: 1857, startWhen: "1526", endWhen: "1857",
      parents: ["timurid"], into: ["british-raj"],
      text: "Empire founded by Babur in 1526. Akbar allowed freedom of religion at court, Shah Jahan's reign produced the Taj Mahal and Aurangzeb reached its greatest extent; it fragmented after 1712 and was dissolved by the British in 1857.",
      cites: [{ t: "Mughal Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Mughal_Empire" }] },
    { id: "sui", name: "Sui dynasty", region: "eastasia",
      start: 581, end: 618, startWhen: "March 4, 581", endWhen: "618",
      parents: ["china-division"], into: ["tang"],
      text: "Dynasty of Yang Jian (Emperor Wen), who reunited China in 589, ending the Northern and Southern dynasties. It dug the Grand Canal but was drained by failed wars on Goguryeo; Li Yuan replaced it with the Tang in 618.",
      cites: [{ t: "Sui dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Sui_dynasty" }] },
    { id: "tang", name: "Tang dynasty", region: "eastasia",
      start: 618, end: 907, startWhen: "618", endWhen: "907",
      parents: ["sui"], into: [],
      text: "Dynasty founded by Li Yuan, ruling from Chang'an, for much of the era the world's most populous city; a cosmopolitan golden age linked to the Silk Road. Interrupted by Wu Zetian (690–705), it ended in 907.",
      cites: [{ t: "Tang dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Tang_dynasty" }] },
    { id: "song", name: "Song dynasty", region: "eastasia",
      start: 960, end: 1279, startWhen: "960", endWhen: "1279",
      parents: [], into: ["yuan"],
      text: "Dynasty that issued the world's first true paper money and left the earliest surviving gunpowder formula. The Jurchen Jin took the north in 1127, leaving the Southern Song, which Kublai Khan's armies conquered in 1279.",
      cites: [{ t: "Song dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Song_dynasty" }] },
    { id: "mongol-empire", name: "Mongol Empire", region: "eastasia",
      start: 1206, end: 1368, startWhen: "1206", endWhen: "1368",
      parents: [], into: [],
      text: "The largest contiguous empire in history, begun when a kurultai proclaimed Temüjin Genghis Khan in 1206. By Kublai's death in 1294 it had fractured into four khanates; the Yuan fell in 1368.",
      cites: [{ t: "Mongol Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Mongol_Empire" }] },
    { id: "yuan", name: "Yuan dynasty", region: "eastasia",
      start: 1271, end: 1368, startWhen: "1271", endWhen: "September 14, 1368",
      parents: ["mongol-empire"], into: ["ming"],
      text: "Mongol-ruled dynasty named “Great Yuan” by Kublai Khan in 1271, with its capital at Khanbaliq (Beijing). It completed the conquest of the Southern Song in 1279, failed to invade Japan, and lost Dadu to the Ming in 1368.",
      cites: [{ t: "Yuan dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Yuan_dynasty" }] },
    { id: "ming", name: "Ming dynasty", region: "eastasia",
      start: 1368, end: 1644, startWhen: "1368", endWhen: "1644",
      parents: ["yuan"], into: ["qing"],
      text: "Dynasty founded by Zhu Yuanzhang (Hongwu Emperor) after the Yuan collapsed. It sent Zheng He's fleets into the Indian Ocean and gave the Great Wall its modern form; Li Zicheng's rebels took Beijing in 1644 and the Qing took over.",
      cites: [{ t: "Ming dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Ming_dynasty" }] },
    { id: "qing", name: "Qing dynasty", region: "eastasia",
      start: 1644, end: 1912, startWhen: "1644", endWhen: "February 12, 1912",
      parents: ["ming"], into: ["roc"],
      text: "Manchu-founded dynasty (Later Jin 1616, named Qing 1636) that took Beijing in 1644. It reached its apex under Qianlong (1735–1796); the Xuantong Emperor's abdication in 1912 ended it and the Republic of China followed.",
      cites: [{ t: "Qing dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Qing_dynasty" }] },
    { id: "unified-silla", name: "Unified Silla", region: "eastasia",
      start: 668, end: 935, startWhen: "668", endWhen: "935",
      parents: ["korea-three-kingdoms"], into: ["goryeo"],
      text: "Silla, allied with Tang China, conquered Baekje (660) and Goguryeo (668), ending the Three Kingdoms period, then fought the Tang for nearly a decade. Balhae held the north; Silla's last king submitted to Goryeo in 935.",
      cites: [{ t: "Unified Silla — Wikipedia", u: "https://en.wikipedia.org/wiki/Unified_Silla" }] },
    { id: "goryeo", name: "Goryeo", region: "eastasia",
      start: 918, end: 1392, startWhen: "918", endWhen: "1392",
      parents: [], into: ["joseon"],
      text: "Korean kingdom founded in 918 by the general Wang Kŏn; it unified the Later Three Kingdoms in 936. It was a Yuan vassal (1270–1356), and General Yi Sŏnggye's coup ended it in 1392. Its name is the source of “Korea.”",
      cites: [{ t: "Goryeo — Wikipedia", u: "https://en.wikipedia.org/wiki/Goryeo" }] },
    { id: "joseon", name: "Joseon", region: "eastasia",
      start: 1392, end: 1897, startWhen: "1392", endWhen: "October 13, 1897",
      parents: ["goryeo"], into: ["korean-empire"],
      text: "Korean kingdom founded by Taejo (Yi Sŏnggye) with Neo-Confucianism as state ideology. It survived Japanese invasions (1592–1598) and Manchu ones (1627, 1636–1637), and was replaced by the Korean Empire in 1897.",
      cites: [{ t: "Joseon — Wikipedia", u: "https://en.wikipedia.org/wiki/Joseon" }] },
    { id: "aztec", name: "Aztec Empire (Triple Alliance)", region: "americas",
      start: 1428, end: 1521, startWhen: "1428", endWhen: "August 13, 1521",
      parents: ["first-americans"], into: ["new-spain"],
      text: "Alliance of the city-states Tenochtitlan, Tetzcoco and Tlacopan that ruled in and around the Valley of Mexico from 1428. Spaniards and their Indigenous allies defeated it in 1521, and New Spain succeeded it.",
      cites: [{ t: "Aztec Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Aztec_Empire" }] },
    { id: "inca", name: "Inca Empire", region: "americas",
      start: 1438, end: 1533, startWhen: "1438 (Pachacuti's expansion)", endWhen: "1533 (Neo-Inca state to 1572)",
      parents: ["first-americans"], into: ["viceroyalty-peru"],
      text: "Largest empire in pre-Columbian America, run from Cusco with Quechua as official language and a vast road network. Pachacuti began its expansion in 1438; Spaniards executed Atahualpa in 1533 and took the last Inca stronghold in 1572.",
      cites: [{ t: "Inca Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Inca_Empire" }] },
    { id: "new-spain", name: "New Spain (viceroyalty)", region: "americas",
      start: 1521, end: 1821, startWhen: "1521 (viceroyalty from 1535)", endWhen: "1821",
      parents: ["aztec", "spain"], into: ["mexico"],
      text: "Named by Cortés after he conquered the Aztec Empire in 1521; a viceroyalty from 1535, ruled from Mexico City, built on Tenochtitlan. It claimed the Philippines, tied by Acapulco's Pacific trade; in 1821 it gave way to the Mexican Empire.",
      cites: [{ t: "New Spain — Wikipedia", u: "https://en.wikipedia.org/wiki/New_Spain" }] },
    { id: "viceroyalty-peru", name: "Viceroyalty of Peru", region: "americas",
      start: 1542, end: 1824, startWhen: "1542", endWhen: "December 9, 1824",
      parents: ["inca", "spain"], into: [],
      text: "Spanish viceroyalty created in 1542 over most of Spanish South America, ruled from Lima (founded 1535). Potosí became the world's largest silver mine; New Granada (1717) and Río de la Plata (1776) split off; it ended at Ayacucho, 1824.",
      cites: [{ t: "Viceroyalty of Peru — Wikipedia", u: "https://en.wikipedia.org/wiki/Viceroyalty_of_Peru" }] },
    { id: "colonial-brazil", name: "Colonial Brazil", region: "americas",
      start: 1500, end: 1815, startWhen: "April 22, 1500", endWhen: "December 16, 1815",
      parents: ["portugal", "first-americans"], into: ["brazil"],
      text: "Portuguese colony from Cabral's landing in 1500. Its sugar plantations shifted from enslaved Indigenous to enslaved African labor, and about 35% of all Africans in the Atlantic slave trade were sent there; it became a kingdom in 1815.",
      cites: [{ t: "Colonial Brazil — Wikipedia", u: "https://en.wikipedia.org/wiki/Colonial_Brazil" }] },
    { id: "thirteen-colonies", name: "Thirteen Colonies", region: "americas",
      start: 1607, end: 1776, startWhen: "1607", endWhen: "1776",
      parents: ["england"], into: ["usa"],
      text: "British colonies on North America's Atlantic coast, from Virginia (Jamestown, 1607) to Georgia (1732); slavery was legal in all of them. They declared independence in 1776 and joined to form the United States.",
      cites: [{ t: "Thirteen Colonies — Wikipedia", u: "https://en.wikipedia.org/wiki/Thirteen_Colonies" }, { t: "History & Culture — Historic Jamestowne, National Park Service", u: "https://www.nps.gov/jame/learn/historyculture/index.htm" }] },
    { id: "usa", name: "United States", region: "americas",
      start: 1776, end: null, startWhen: "July 4, 1776", endWhen: "",
      parents: ["thirteen-colonies"], into: [],
      text: "Republic formed when the 13 colonies cut their ties to Great Britain: Congress adopted the final text of the Jefferson-drafted Declaration of Independence on July 4, 1776.",
      cites: [{ t: "Declaration of Independence: A Transcription — U.S. National Archives", u: "https://www.archives.gov/founding-docs/declaration" },
              { t: "Thirteen Colonies — Wikipedia", u: "https://en.wikipedia.org/wiki/Thirteen_Colonies" }, { t: "The Declaration of Independence, 1776 — Office of the Historian", u: "https://history.state.gov/milestones/1776-1783/declaration" }] },
    { id: "maori", name: "Māori", region: "oceania",
      start: 1320, end: null, startWhen: "c. 1320–1350 (some studies: 1250–1275)", endWhen: "",
      parents: ["polynesians"], into: [],
      text: "Indigenous people of New Zealand, descended from Polynesian settlers who arrived in several waves of canoe voyages c. 1320–1350 (a 2022 study suggests 1250–1275 for the North Island).",
      cites: [{ t: "Māori people — Wikipedia", u: "https://en.wikipedia.org/wiki/M%C4%81ori_people" }] },
    { id: "scientific-revolution", name: "Scientific Revolution", region: "global",
      start: 1543, end: 1687, startWhen: "1543 (or 1572)", endWhen: "1687",
      parents: [], into: ["enlightenment"],
      text: "Period often dated from Vesalius's and Copernicus's books of 1543, culminating in Newton's Principia (1687). Kepler's elliptical orbits, Galileo's telescope work and Harvey's circulation of the blood (1628) belong to it.",
      cites: [{ t: "Scientific Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/Scientific_Revolution" }] },
    { id: "enlightenment", name: "The Enlightenment", region: "global",
      start: 1685, end: 1804, startWhen: "late 17th century (traditionally 1715)", endWhen: "c. 1804 (traditionally 1789)",
      parents: ["scientific-revolution"], into: [],
      text: "European intellectual movement that emerged in the late 17th century from the Scientific Revolution and peaked in the 18th. Locke's natural rights were central to it; Montesquieu's separation of powers shaped the US Constitution.",
      cites: [{ t: "Age of Enlightenment — Wikipedia", u: "https://en.wikipedia.org/wiki/Age_of_Enlightenment" }, { t: "Enlightenment — Stanford Encyclopedia of Philosophy", u: "https://plato.stanford.edu/entries/enlightenment/" }] },
    { id: "industrial-revolution", name: "Industrial Revolution", region: "global",
      start: 1760, end: 1840, startWhen: "c. 1760", endWhen: "c. 1840",
      parents: [], into: [],
      text: "Shift to mechanized manufacturing that began in Great Britain around 1760 — spinning jenny (1764), water frame (1769), Watt's improved steam engine — and had spread to continental Europe and the US by about 1840.",
      cites: [{ t: "Industrial Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/Industrial_Revolution" }] },
    { id: "fatimid", name: "Fatimid Caliphate", region: "mideast",
      start: 909, end: 1171, startWhen: "909", endWhen: "1171",
      parents: [], into: [],
      text: "Isma'ili Shi'a caliphate that rose in Ifriqiya, conquered Egypt in 969 and ruled from its new capital, Cairo, where it built al-Azhar (970–972). Weakened after the Crusaders arrived in 1097, it was abolished by Saladin in 1171.",
      cites: [{ t: "Fatimid Caliphate — Wikipedia", u: "https://en.wikipedia.org/wiki/Fatimid_Caliphate" }] },
    { id: "seljuk", name: "Seljuk Empire", region: "mideast",
      start: 1037, end: 1194, startWhen: "1037", endWhen: "1194 (Sultanate of Rum to 1308)",
      parents: [], into: [],
      text: "Turco-Persianate, Sunni empire of Oghuz Turks. Tughril entered Baghdad in 1055 under an Abbasid commission; it collapsed in 1194 after defeat by Khwarazm, leaving the Sultanate of Rum in Anatolia until 1308.",
      cites: [{ t: "Seljuk Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Seljuk_Empire" }] },
    { id: "timurid", name: "Timurid Empire", region: "mideast",
      start: 1370, end: 1507, startWhen: "1370", endWhen: "1507",
      parents: [], into: [],
      text: "Turco-Mongol, culturally Persianate Muslim empire founded by Timur (Tamerlane, r. 1370–1405), who beat the Ottomans at Ankara in 1402. Samarkand and Herat became seats of Persian culture; the Timurid prince Babur founded the Mughal Empire.",
      cites: [{ t: "Timurid Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Timurid_Empire" }] },
    { id: "vikings", name: "Viking Age Norse", region: "europe",
      start: 793, end: 1066, startWhen: "June 8, 793 (traditional)", endWhen: "1066 (traditional)",
      parents: [], into: [],
      text: "Era of Scandinavian raiding, trading and settlement, often dated from the Lindisfarne raid (793) to Stamford Bridge (1066). Norse settled Normandy and the Danelaw, pioneered Greenland and briefly settled Newfoundland.",
      cites: [{ t: "Viking Age — Wikipedia", u: "https://en.wikipedia.org/wiki/Viking_Age" }] },
    { id: "dutch-republic", name: "Dutch Republic", region: "europe",
      start: 1588, end: 1795, startWhen: "1588 (Union of Utrecht 1579; independence declared 1581)", endWhen: "1795",
      parents: [], into: [],
      text: "Confederation of the northern Low Countries, which formed the Union of Utrecht (1579), declared independence from Spain (1581) and became a republic in 1588. Spain recognized it in 1648; the Batavian Revolution of 1795 ended it.",
      cites: [{ t: "Dutch Republic — Wikipedia", u: "https://en.wikipedia.org/wiki/Dutch_Republic" }] },
    { id: "polish-lithuanian", name: "Polish–Lithuanian Commonwealth", region: "europe",
      start: 1569, end: 1795, startWhen: "July 1, 1569", endWhen: "1795",
      parents: [], into: [],
      text: "State made single by the Union of Lublin (1569) after a personal union since 1385, with an elective monarchy and “Golden Liberty.” Its May 3 Constitution (1791) came as Russia, Prussia and Austria partitioned it (1772, 1793, 1795).",
      cites: [{ t: "Polish–Lithuanian Commonwealth — Wikipedia", u: "https://en.wikipedia.org/wiki/Polish%E2%80%93Lithuanian_Commonwealth" }] },
    { id: "khmer", name: "Khmer Empire", region: "eastasia",
      start: 802, end: 1431, startWhen: "802 (conventional)", endWhen: "1431",
      parents: [], into: [],
      text: "Southeast Asian empire conventionally dated from 802, when Jayavarman II took the title devaraja (“god king”), ruled from Angkor. Hinduism and Mahayana Buddhism were official religions; Angkor fell to Ayutthaya in 1431.",
      cites: [{ t: "Khmer Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Khmer_Empire" }] },
    { id: "vijayanagara", name: "Vijayanagara Empire", region: "southasia",
      start: 1336, end: 1646, startWhen: "1336", endWhen: "1646",
      parents: [], into: [],
      text: "South Indian empire founded in 1336 by the Sangama brothers Harihara I and Bukka Raya I, named for its capital near modern Hampi. It peaked under Krishnadevaraya (r. 1509–1529); its last remnants ended in 1646.",
      cites: [{ t: "Vijayanagara Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Vijayanagara_Empire" }] },
    { id: "benin-kingdom", name: "Kingdom of Benin", region: "africa",
      start: 1180, end: 1897, startWhen: "1180 (Oba monarchy; Edo state from c. 11th century)", endWhen: "1897",
      parents: [], into: [],
      text: "Edo kingdom grown from Igodomigodo; its Oba monarchy dates to 1180. Ewuare the Great (from 1440) expanded it, and it is known for its brass Benin Bronzes. A British force captured Benin City in 1897.",
      cites: [{ t: "Kingdom of Benin — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Benin" }] },
    { id: "kongo", name: "Kingdom of Kongo", region: "africa",
      start: 1390, end: 1914, startWhen: "c. 1390", endWhen: "1914",
      parents: [], into: [],
      text: "Central African kingdom founded around 1390 by a marriage alliance of KiKongo-speaking lineages. Its kings became Christian after Portuguese contact (1483); Portuguese Angola defeated it at Mbwila (1665), and Portugal abolished it in 1914.",
      cites: [{ t: "Kingdom of Kongo — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Kongo" }] },
    { id: "kingdom-of-ireland", name: "Kingdom of Ireland", region: "europe",
      start: 1542, end: 1801, startWhen: "1542", endWhen: "January 1, 1801",
      parents: [], into: ["uk"],
      text: "Kingdom created in 1542 when the Irish Parliament passed Henry VIII's Crown of Ireland Act, succeeding the English Lordship of Ireland (1177). Conquest brought Protestant British settlers; it merged with Great Britain on January 1, 1801.",
      cites: [{ t: "Kingdom of Ireland — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Ireland" }] },
  ],
  events: [
    { id: "me-hijra", branch: "islam", y: 622, when: "622",
      title: "Hijra: Muhammad migrates from Mecca to Medina",
      text: "Muhammad and his followers migrated from Mecca to Yathrib (Medina) in 622; he conquered Mecca around 629/630 and died on June 8, 632.",
      imp: 1, cites: [{ t: "Muhammad — Wikipedia", u: "https://en.wikipedia.org/wiki/Muhammad" }] },
    { id: "me-dome-of-the-rock", branch: "umayyad", y: 691, when: "691/692",
      title: "Dome of the Rock completed in Jerusalem",
      text: "Caliph Abd al-Malik completed the Dome of the Rock in Jerusalem in 691/692.",
      imp: 3, cites: [{ t: "Umayyad Caliphate — Wikipedia", u: "https://en.wikipedia.org/wiki/Umayyad_Caliphate" }] },
    { id: "me-talas", branch: "abbasid", y: 751, when: "751",
      title: "Battle of Talas: Abbasids defeat a Tang army",
      text: "A Tang army under Gao Xianzhi was defeated in 751 at the Battle of Talas, near present-day Tashkent, as Abbasid and Chinese power met in Central Asia.",
      imp: 2, link: "tang", cites: [{ t: "Abbasid Caliphate — Wikipedia", u: "https://en.wikipedia.org/wiki/Abbasid_Caliphate" }] },
    { id: "me-baghdad-founded", branch: "abbasid", y: 762, when: "762",
      title: "Al-Mansur founds Baghdad",
      text: "The second Abbasid caliph, al-Mansur, founded Baghdad in 762 and made it the capital; it later hosted institutions such as the House of Wisdom.",
      imp: 3, cites: [{ t: "Abbasid Caliphate — Wikipedia", u: "https://en.wikipedia.org/wiki/Abbasid_Caliphate" }] },
    { id: "me-cordoba-caliphate", branch: "al-andalus", y: 929, when: "929",
      title: "Abd al-Rahman III declares the Caliphate of Córdoba",
      text: "Abd al-Rahman III declared himself caliph in 929; the Caliphate of Córdoba lasted until 1031, after which al-Andalus broke up into taifa states.",
      imp: 3, cites: [{ t: "Al-Andalus — Wikipedia", u: "https://en.wikipedia.org/wiki/Al-Andalus" }] },
    { id: "me-justinian-code", branch: "byzantine", y: 529, when: "April 7, 529",
      title: "Justinian issues his law code",
      text: "Emperor Justinian I (r. 527–565) issued the Codex on April 7, 529 (final version 534), followed by the Digest of older legal texts in 533 — the body of law later called the Corpus Juris Civilis.",
      imp: 2, cites: [{ t: "Justinian I — Wikipedia", u: "https://en.wikipedia.org/wiki/Justinian_I" }] },
    { id: "me-hagia-sophia", branch: "byzantine", y: 537, when: "December 26, 537",
      title: "Justinian's Hagia Sophia inaugurated",
      text: "After the Nika riots of January 532 damaged Constantinople, Justinian rebuilt Hagia Sophia on the site; its completion was marked on December 26, 537.",
      imp: 3, cites: [{ t: "Justinian I — Wikipedia", u: "https://en.wikipedia.org/wiki/Justinian_I" }] },
    { id: "me-battle-of-tours", branch: "franks", y: 732, when: "October 10, 732",
      title: "Battle of Tours",
      text: "Frankish and Aquitanian forces under Charles Martel defeated an Umayyad army led by Abd al-Rahman al-Ghafiqi, who was killed. Historians debate whether it was a decisive turning point or a repulsed large raid.",
      imp: 2, link: "umayyad", cites: [{ t: "Battle of Tours — Wikipedia", u: "https://en.wikipedia.org/wiki/Battle_of_Tours" }] },
    { id: "me-charlemagne-crowned", branch: "franks", y: 800, when: "December 25, 800",
      title: "Charlemagne crowned Emperor of the Romans",
      text: "Pope Leo III crowned the Frankish king Charles “Emperor of the Romans” in Rome on Christmas Day 800 — one of the two dates given for the start of the Holy Roman Empire.",
      imp: 1, link: "christianity", cites: [{ t: "Francia — Wikipedia", u: "https://en.wikipedia.org/wiki/Francia" }, { t: "Holy Roman Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Holy_Roman_Empire" }] },
    { id: "me-treaty-of-verdun", branch: "franks", y: 843, when: "August 843",
      title: "Treaty of Verdun splits the Carolingian empire",
      text: "After Louis the Pious died, his three sons divided the Carolingian empire into three parts: Charles the Bald received the west and Louis the German the mostly Germanic-speaking east.",
      imp: 3, cites: [{ t: "Francia — Wikipedia", u: "https://en.wikipedia.org/wiki/Francia" }, { t: "West Francia — Wikipedia", u: "https://en.wikipedia.org/wiki/West_Francia" }, { t: "East Francia — Wikipedia", u: "https://en.wikipedia.org/wiki/East_Francia" }] },
    { id: "me-house-of-wisdom", branch: "abbasid", y: 830, when: "9th century (under al-Ma'mun)",
      title: "House of Wisdom flourishes in Baghdad",
      text: "Under al-Ma'mun the House of Wisdom became a public academy and library where scholars put Greek and Syriac works into Arabic and al-Khwarizmi worked; some historians doubt it was a formal academy. The Mongols destroyed it in 1258.",
      imp: 2, cites: [{ t: "House of Wisdom — Wikipedia", u: "https://en.wikipedia.org/wiki/House_of_Wisdom" }] },
    { id: "me-normandy-settled", branch: "vikings", y: 911, when: "911",
      title: "Norse settlement of Normandy",
      text: "After Robert of Neustria defeated the Viking leader Rollo at Chartres in 911, Norsemen settled in the region of West Francia that became Normandy.",
      imp: 3, link: "west-francia", cites: [{ t: "West Francia — Wikipedia", u: "https://en.wikipedia.org/wiki/West_Francia" }, { t: "Viking Age — Wikipedia", u: "https://en.wikipedia.org/wiki/Viking_Age" }] },
    { id: "me-rus-baptism", branch: "kievan-rus", y: 988, when: "August 988",
      title: "Vladimir has Kiev baptized",
      text: "Grand Prince Vladimir was baptized and ordered Kiev's people baptized in August 988, likely choosing Byzantine Christianity partly to strengthen ties with Constantinople.",
      imp: 2, link: "byzantine", cites: [{ t: "Kievan Rus' — Wikipedia", u: "https://en.wikipedia.org/wiki/Kievan_Rus%27" }] },
    { id: "me-great-schism", branch: "catholicism", y: 1054, when: "1054",
      title: "East–West Schism: mutual excommunications",
      text: "Papal legate Cardinal Humbert excommunicated Patriarch Michael Cerularius, who excommunicated the legates in turn, amid disputes over papal authority and the Filioque. The anathemas were nullified only in 1965.",
      imp: 1, link: "orthodoxy", cites: [{ t: "East–West Schism — Wikipedia", u: "https://en.wikipedia.org/wiki/East%E2%80%93West_Schism" }] },
    { id: "me-hastings", branch: "england", y: 1066.78, when: "October 14, 1066",
      title: "Norman Conquest: Battle of Hastings",
      text: "Weeks after Harold Godwinson beat Harald Hardrada at Stamford Bridge, William's Normans defeated him at Hastings; William was crowned on December 25, 1066. Anglo-Norman French became the language of England's ruling class.",
      imp: 1, link: "france", cites: [{ t: "Norman Conquest — Wikipedia", u: "https://en.wikipedia.org/wiki/Norman_Conquest" }] },
    { id: "me-manzikert", branch: "seljuk", y: 1071, when: "1071",
      title: "Battle of Manzikert",
      text: "The Seljuk victory at Manzikert in 1071 was a decisive turning point in the Byzantine–Seljuk wars.",
      imp: 3, link: "byzantine", cites: [{ t: "Seljuk Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Seljuk_Empire" }] },
    { id: "me-fourth-crusade", branch: "byzantine", y: 1204, when: "1204",
      title: "Fourth Crusade sacks Constantinople",
      text: "The schism between Rome and Constantinople culminated in the crusaders' sack and pillage of Constantinople in 1204, followed by the imposition of Latin patriarchs.",
      imp: 2, link: "catholicism", cites: [{ t: "East–West Schism — Wikipedia", u: "https://en.wikipedia.org/wiki/East%E2%80%93West_Schism" }] },
    { id: "me-first-crusade", branch: "catholicism", y: 1095.9, end: 1099.54, when: "November 27, 1095 – July 15, 1099",
      title: "First Crusade: crusaders take Jerusalem",
      text: "Answering a Byzantine plea for aid against the Turks, Pope Urban II preached at Clermont in 1095. Crusaders stormed Fatimid-held Jerusalem on July 15, 1099, massacring many residents, and founded four Crusader states.",
      imp: 1, link: "fatimid", cites: [{ t: "First Crusade — Wikipedia", u: "https://en.wikipedia.org/wiki/First_Crusade" }] },
    { id: "me-magna-carta", branch: "england", y: 1215.45, when: "June 15, 1215",
      title: "Magna Carta sealed at Runnymede",
      text: "King John sealed the charter at Runnymede to make peace with rebel barons. Pope Innocent III annulled it, leading to the First Barons' War, but it was reissued in 1216, 1217 and 1225; four 1215 copies survive.",
      imp: 1, cites: [{ t: "Magna Carta — Wikipedia", u: "https://en.wikipedia.org/wiki/Magna_Carta" }] },
    { id: "me-mongols-take-rus", branch: "mongol-empire", y: 1240, when: "by 1240",
      title: "Mongols overrun Kievan Rus'",
      text: "By 1240 all of Kievan Rus' except a few northern cities had fallen to the Mongols; they beat a Hungarian army on April 11, 1241, and Batu withdrew from Central Europe the next year.",
      imp: 2, link: "kievan-rus", cites: [{ t: "Mongol Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Mongol_Empire" }] },
    { id: "me-sack-of-baghdad", branch: "ilkhanate", y: 1258, when: "1258",
      title: "Mongols sack Baghdad, ending the Abbasid caliphate",
      text: "Hulagu's Mongols besieged, captured and sacked Baghdad in 1258, ending the Abbasid caliphate there; the House of Wisdom was destroyed.",
      imp: 1, link: "abbasid", cites: [{ t: "Mongol Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Mongol_Empire" }, { t: "Abbasid Caliphate — Wikipedia", u: "https://en.wikipedia.org/wiki/Abbasid_Caliphate" }] },
    { id: "me-black-death", branch: "golden-horde", y: 1346, end: 1353, when: "1346–1353",
      title: "Black Death",
      text: "Plague (Yersinia pestis) reportedly reached Europe in 1347 from the Golden Horde's siege of Genoese Caffa in Crimea, then spread by ship. It killed an estimated 25–50 million, some 30–60% of Europe's population.",
      imp: 1, cites: [{ t: "Black Death — Wikipedia", u: "https://en.wikipedia.org/wiki/Black_Death" }] },
    { id: "me-gutenberg-bible", branch: "hre", y: 1455, when: "1455 (press running by 1450)",
      title: "Gutenberg completes his printed Bible",
      text: "Johannes Gutenberg, inventor of the movable-type printing press, had a press running by 1450 and completed his 42-line Bible in 1455. Printing spread literature across Europe on an unprecedented scale.",
      imp: 1, cites: [{ t: "Johannes Gutenberg — Wikipedia", u: "https://en.wikipedia.org/wiki/Johannes_Gutenberg" }] },
    { id: "me-columbus-landfall", branch: "spain", y: 1492.78, when: "October 12, 1492",
      title: "Columbus reaches the Americas",
      text: "Sailing for the Catholic Monarchs from Palos on August 3, Columbus landed on Guanahani (San Salvador, Bahamas) on October 12, 1492, and met Lucayan and Taíno peoples, opening European colonization of the Americas.",
      imp: 1, link: "first-americans", cites: [{ t: "Voyages of Christopher Columbus — Wikipedia", u: "https://en.wikipedia.org/wiki/Voyages_of_Christopher_Columbus" }, { t: "Spanish Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Spanish_Empire" }] },
    { id: "me-columbian-exchange", branch: "first-americans", y: 1493, end: 1650, when: "from the late 15th century",
      title: "The Columbian exchange",
      text: "Plants, animals and diseases crossed between the Americas and Afro-Eurasia: maize and potatoes spread worldwide and horses reshaped Native life, while smallpox and other epidemics killed 80–95% of Native Americans within 100–150 years.",
      imp: 1, link: "spain", cites: [{ t: "Columbian exchange — Wikipedia", u: "https://en.wikipedia.org/wiki/Columbian_exchange" }] },
    { id: "me-tordesillas", branch: "spain", y: 1494.43, when: "June 7, 1494",
      title: "Treaty of Tordesillas divides the world",
      text: "Castile and Portugal split newly found lands along a meridian 370 leagues west of the Cape Verde islands, giving Portugal the eastern part of what is now Brazil.",
      imp: 2, link: "portugal", cites: [{ t: "Treaty of Tordesillas — Wikipedia", u: "https://en.wikipedia.org/wiki/Treaty_of_Tordesillas" }] },
    { id: "me-da-gama-calicut", branch: "portugal", y: 1498.38, when: "May 20, 1498",
      title: "Vasco da Gama reaches India by sea",
      text: "On his 1497–1499 voyage around the Cape of Good Hope, da Gama landed at Kozhikode (Calicut) on May 20, 1498 — the first voyage to link Europe and Asia by an ocean route.",
      imp: 2, cites: [{ t: "Vasco da Gama — Wikipedia", u: "https://en.wikipedia.org/wiki/Vasco_da_Gama" }] },
    { id: "me-copernicus", branch: "scientific-revolution", y: 1543, when: "1543",
      title: "Copernicus publishes De revolutionibus",
      text: "Copernicus's book, printed in Nuremberg in 1543, put a stationary Sun at the center with the Earth revolving around it; he is said to have held a finished copy on his deathbed on May 24, 1543.",
      imp: 2, cites: [{ t: "Nicolaus Copernicus — Stanford Encyclopedia of Philosophy", u: "https://plato.stanford.edu/entries/copernicus/" }] },
    { id: "me-akbar", branch: "mughal", y: 1556, end: 1605, when: "1556–1605",
      title: "Reign of Akbar",
      text: "Akbar enlarged the empire across much of the subcontinent, abolished the jizya tax on non-Muslims, allied with Rajput houses through marriage and organized nobles in the mansabdari system.",
      imp: 2, cites: [{ t: "Akbar — Wikipedia", u: "https://en.wikipedia.org/wiki/Akbar" }] },
    { id: "me-atlantic-slave-trade", branch: "portugal", y: 1525, when: "from 1525 (direct Africa–Americas voyages)",
      title: "Atlantic slave trade to the Americas",
      text: "From 1525 enslaved Africans were shipped directly from São Tomé to Hispaniola. About 12.75 million Africans were loaded onto slave ships over the following centuries; up to 2 million died on the voyage.",
      imp: 1, link: "colonial-brazil", cites: [{ t: "Atlantic slave trade — Wikipedia", u: "https://en.wikipedia.org/wiki/Atlantic_slave_trade" }] },
    { id: "me-galileo-sidereus", branch: "scientific-revolution", y: 1610.2, when: "March 1610",
      title: "Galileo's Sidereus Nuncius",
      text: "With his telescope Galileo found four moons orbiting Jupiter in January 1610 and published them in March; the finding supported Copernicus. Convicted by the Inquisition in 1633, he spent his last years under house arrest.",
      imp: 2, cites: [{ t: "Galileo Galilei — Wikipedia", u: "https://en.wikipedia.org/wiki/Galileo_Galilei" }, { t: "Galileo Galilei — Stanford Encyclopedia of Philosophy", u: "https://plato.stanford.edu/entries/galileo/" }] },
    { id: "me-thirty-years-war", branch: "hre", y: 1618, end: 1648, when: "1618–1648",
      title: "Thirty Years' War",
      text: "Rooted in religious conflict within the Empire and widened by French–Habsburg rivalry, it killed an estimated 4.5–8 million. The Peace of Westphalia (October 1648) ended it, giving states more autonomy and Sweden lands.",
      imp: 1, link: "france", cites: [{ t: "Thirty Years' War — Wikipedia", u: "https://en.wikipedia.org/wiki/Thirty_Years%27_War" }, { t: "Peace of Westphalia — Wikipedia", u: "https://en.wikipedia.org/wiki/Peace_of_Westphalia" }] },
    { id: "me-watt-condenser", branch: "industrial-revolution", y: 1769, when: "1769 (idea May 1765)",
      title: "Watt patents the separate condenser",
      text: "James Watt improved Newcomen's 1712 engine with a separate condenser, conceived in 1765 and patented in 1769; partnered with Matthew Boulton from 1775, his engines were fundamental to the Industrial Revolution.",
      imp: 1, cites: [{ t: "James Watt — Wikipedia", u: "https://en.wikipedia.org/wiki/James_Watt" }] },
    { id: "me-buddhism-to-japan", branch: "japan", y: 552, when: "552 (Nihon Shoki; other sources 538)",
      title: "Buddhism arrives in Japan from Baekje",
      text: "The Nihon Shoki dates to 552 a mission from King Seong of Baekje to Emperor Kinmei carrying a Buddha image and sutras, usually treated as Buddhism's official introduction; other sources give 538, and both are considered unreliable.",
      imp: 2, link: "korea-three-kingdoms", cites: [{ t: "Buddhism in Japan — Wikipedia", u: "https://en.wikipedia.org/wiki/Buddhism_in_Japan" }, { t: "Japan timeline — Asia for Educators, Columbia University", u: "https://afe.easia.columbia.edu/timelines/japan_timeline.htm" }] },
    { id: "me-grand-canal", branch: "sui", y: 605, end: 609, when: "605–609",
      title: "Sui dig the Grand Canal",
      text: "Begun under Emperor Wen and greatly expanded by Emperor Yang, the Grand Canal was dug between 605 and 609 with enormous levies of conscripted labor.",
      imp: 3, cites: [{ t: "Sui dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Sui_dynasty" }] },
    { id: "me-taika-reform", branch: "japan", y: 645, when: "645–646",
      title: "Taika Reform",
      text: "Under Emperor Kōtoku, Prince Naka no Ōe and Nakatomi no Kamatari launched reforms (edicts of 646) inspired by missions to Sui and Tang China, aiming to emulate China's centralized imperial control.",
      imp: 3, link: "tang", cites: [{ t: "Taika Reform — Wikipedia", u: "https://en.wikipedia.org/wiki/Taika_Reform" }, { t: "Japan timeline — Asia for Educators, Columbia University", u: "https://afe.easia.columbia.edu/timelines/japan_timeline.htm" }] },
    { id: "me-silla-unifies", branch: "unified-silla", y: 668, when: "660–668",
      title: "Silla–Tang alliance conquers Baekje and Goguryeo",
      text: "Allied with Tang China, Silla attacked Baekje in 660 and conquered Goguryeo in 668, ending Korea's Three Kingdoms period; Silla then fought the Tang in the Silla–Tang War of 670–676.",
      imp: 3, link: "tang", cites: [{ t: "Unified Silla — Wikipedia", u: "https://en.wikipedia.org/wiki/Unified_Silla" }] },
    { id: "me-an-lushan", branch: "tang", y: 755, end: 763, when: "755–763",
      title: "An Lushan rebellion",
      text: "The An Lushan rebellion devastated Tang China and led to the decline of central authority in the dynasty's second half.",
      imp: 2, cites: [{ t: "Tang dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Tang_dynasty" }] },
    { id: "me-diamond-sutra", branch: "tang", y: 868, when: "May 11, 868",
      title: "Diamond Sutra: oldest dated printed book",
      text: "A woodblock-printed Diamond Sutra dated May 11, 868, found in the Mogao Caves near Dunhuang and now in the British Library, is broadly considered the oldest extant printed book.",
      imp: 3, cites: [{ t: "Diamond Sutra — Wikipedia", u: "https://en.wikipedia.org/wiki/Diamond_Sutra" }] },
    { id: "me-tale-of-genji", branch: "japan", y: 1008, when: "early 11th century (mentioned 1008)",
      title: "The Tale of Genji",
      text: "Murasaki Shikibu's tale of the Heian court, mentioned in a diary in 1008 and generally thought finished by 1021, is often called “the first novel,” though that label is debated.",
      imp: 3, cites: [{ t: "The Tale of Genji — Wikipedia", u: "https://en.wikipedia.org/wiki/The_Tale_of_Genji" }] },
    { id: "me-bi-sheng-type", branch: "song", y: 1041, when: "1041–1048",
      title: "Bi Sheng's movable type",
      text: "Bi Sheng printed with movable type made of fired clay, one piece per character, in the Qingli reign (1041–1048); the invention is recorded only in Shen Kuo's Dream Pool Essays.",
      imp: 2, cites: [{ t: "Bi Sheng — Wikipedia", u: "https://en.wikipedia.org/wiki/Bi_Sheng" }] },
    { id: "me-angkor-wat", branch: "khmer", y: 1113, end: 1150, when: "reign of Suryavarman II, 1113–1150",
      title: "Angkor Wat built",
      text: "Under Suryavarman II the Khmer built Angkor Wat, dedicated to the Hindu god Vishnu, over a period of 37 years.",
      imp: 2, cites: [{ t: "Khmer Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Khmer_Empire" }] },
    { id: "me-southern-song", branch: "song", y: 1127, when: "1127",
      title: "Jurchen Jin take the Song capital",
      text: "The Jurchen-led Jin captured the Song capital in the Jingkang Incident; the court moved south, dividing the Northern from the Southern Song.",
      imp: 3, cites: [{ t: "Song dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Song_dynasty" }] },
    { id: "me-kamakura", branch: "japan", y: 1185, end: 1333, when: "1185/1192–1333",
      title: "Kamakura shogunate",
      text: "After winning the Genpei War, Minamoto no Yoritomo founded the Kamakura shogunate (start dated 1185 or 1192, when he became shōgun); Emperor Go-Daigo's Kenmu Restoration overthrew it in 1333.",
      imp: 3, cites: [{ t: "Kamakura shogunate — Wikipedia", u: "https://en.wikipedia.org/wiki/Kamakura_shogunate" }, { t: "Japan timeline — Asia for Educators, Columbia University", u: "https://afe.easia.columbia.edu/timelines/japan_timeline.htm" }] },
    { id: "me-tripitaka-koreana", branch: "goryeo", y: 1236, end: 1251, when: "from 1236 (15 years)",
      title: "Tripitaka Koreana carved",
      text: "After a 1232 Mongol invasion destroyed the earlier set, King Gojong ordered the Buddhist canon recarved in 1236; the work took 15 years and some 81,000 wooden blocks.",
      imp: 3, link: "mongol-empire", cites: [{ t: "Goryeo — Wikipedia", u: "https://en.wikipedia.org/wiki/Goryeo" }] },
    { id: "me-mongol-invasions-japan", branch: "japan", y: 1274, end: 1281, when: "1274 and 1281",
      title: "Mongol invasions of Japan fail",
      text: "Kublai Khan's Yuan fleets attacked Japan in 1274 and 1281; Kamakura's defenders held and typhoons wrecked much of the invading forces, ending Mongol attempts to conquer Japan.",
      imp: 2, link: "yuan", cites: [{ t: "Yuan dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Yuan_dynasty" }, { t: "Kamakura shogunate — Wikipedia", u: "https://en.wikipedia.org/wiki/Kamakura_shogunate" }] },
    { id: "me-song-falls", branch: "yuan", y: 1279, when: "1279",
      title: "Battle of Yamen: Mongols finish the Song",
      text: "Kublai Khan's armies defeated the Southern Song at the Battle of Yamen in 1279, completing the Mongol conquest of China.",
      imp: 2, link: "song", cites: [{ t: "Yuan dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Yuan_dynasty" }, { t: "Song dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Song_dynasty" }] },
    { id: "me-jikji", branch: "goryeo", y: 1377.5, when: "July 1377",
      title: "Jikji printed with metal movable type",
      text: "Printed at Heungdeok Temple near Cheongju in 1377, the Jikji is the world's oldest extant book printed with movable metal type; its surviving volume is in France's national library.",
      imp: 3, cites: [{ t: "Jikji — Wikipedia", u: "https://en.wikipedia.org/wiki/Jikji" }] },
    { id: "me-zheng-he", branch: "ming", y: 1405, when: "from 1405",
      title: "Zheng He's voyages begin",
      text: "Under the Yongle Emperor, the eunuch admiral Zheng He led seven enormous voyages of exploration into the Indian Ocean, beginning in 1405.",
      imp: 2, cites: [{ t: "Ming dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Ming_dynasty" }] },
    { id: "me-forbidden-city", branch: "ming", y: 1407, end: 1420, when: "1407–1420",
      title: "Forbidden City built in Beijing",
      text: "In 1403 the Yongle Emperor announced that Beijing would be China's new capital; a new city was built there from 1407 to 1420, with the Forbidden City, the emperor's palace, at its center.",
      imp: 3, cites: [{ t: "Ming dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Ming_dynasty" }] },
    { id: "me-hangul", branch: "joseon", y: 1446.77, when: "created 1443, promulgated October 9, 1446",
      title: "King Sejong's Hangul alphabet",
      text: "King Sejong's best-remembered contribution was Hangul, the Korean alphabet, created in 1443 and promulgated in 1446.",
      imp: 2, cites: [{ t: "Joseon — Wikipedia", u: "https://en.wikipedia.org/wiki/Joseon" }] },
    { id: "me-imjin-war", branch: "joseon", y: 1592, end: 1598, when: "1592–1598",
      title: "Japanese invasions of Korea",
      text: "Japan's invasions of Joseon (1592–1598) failed; Admiral Yi Sun-sin slowed the invasion by destroying the Japanese fleet.",
      imp: 2, link: "japan", cites: [{ t: "Joseon — Wikipedia", u: "https://en.wikipedia.org/wiki/Joseon" }] },
    { id: "me-tokugawa", branch: "japan", y: 1603, end: 1868, when: "1603–1868",
      title: "Tokugawa shogunate rules from Edo",
      text: "After victory at Sekigahara (October 21, 1600), Tokugawa Ieyasu founded a shogunate that governed Japan from Edo Castle until the Meiji Restoration of 1868.",
      imp: 1, cites: [{ t: "Tokugawa shogunate — Wikipedia", u: "https://en.wikipedia.org/wiki/Tokugawa_shogunate" }] },
    { id: "me-sakoku", branch: "japan", y: 1635, when: "1635",
      title: "Sakoku: Japan closes its doors",
      text: "Tokugawa seclusion laws of 1635 barred the entry of most foreigners; inbound ships were allowed only from China, Korea and the Netherlands, the Dutch trading from Dejima.",
      imp: 2, link: "dutch-republic", cites: [{ t: "Tokugawa shogunate — Wikipedia", u: "https://en.wikipedia.org/wiki/Tokugawa_shogunate" }] },
    { id: "me-manchu-invasions-korea", branch: "joseon", y: 1627, end: 1637, when: "1627 and 1636–1637",
      title: "Manchu invasions of Joseon",
      text: "Joseon was invaded by the Later Jin in 1627 and by the Qing in 1636–1637.",
      imp: 3, link: "qing", cites: [{ t: "Joseon — Wikipedia", u: "https://en.wikipedia.org/wiki/Joseon" }] },
    { id: "me-qing-taiwan", branch: "qing", y: 1683, when: "1683",
      title: "Qing receive the surrender of Taiwan",
      text: "In 1683 Qing forces received the surrender of Formosa (Taiwan) from Zheng Keshuang, grandson of Koxinga.",
      imp: 3, cites: [{ t: "Qing dynasty — Wikipedia", u: "https://en.wikipedia.org/wiki/Qing_dynasty" }] },
    { id: "me-ain-jalut", branch: "ilkhanate", y: 1260.67, when: "September 3, 1260",
      title: "Battle of Ain Jalut",
      text: "Mamluk forces under Qutuz and Baybars defeated the Ilkhanate army of Kitbuqa in the Jezreel Valley — often called the first major halt to Mongol advances; the Mongols withdrew from the Levant.",
      imp: 2, cites: [{ t: "Battle of Ain Jalut — Wikipedia", u: "https://en.wikipedia.org/wiki/Battle_of_Ain_Jalut" }] },
    { id: "me-mansa-musa-hajj", branch: "mali", y: 1324, end: 1325, when: "1324–1325",
      title: "Mansa Musa's pilgrimage to Mecca",
      text: "Mansa Musa reached Cairo in July 1324 en route to Mecca; his lavish gifts are said to have noticeably affected the value of gold in Egypt. He recruited scholars, such as al-Sahili, to come to Mali.",
      imp: 2, cites: [{ t: "Mansa Musa — Wikipedia", u: "https://en.wikipedia.org/wiki/Mansa_Musa" }, { t: "Mali Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Mali_Empire" }] },
    { id: "me-timur-delhi", branch: "delhi-sultanate", y: 1398, when: "1398",
      title: "Timur sacks Delhi",
      text: "Timur's 1398 sack of Delhi, estimated to have killed 100,000–200,000 people, left the Delhi Sultanate in shambles; skilled artisans were spared the massacre but enslaved and taken to Samarkand.",
      imp: 2, link: "timurid", cites: [{ t: "Delhi Sultanate — Wikipedia", u: "https://en.wikipedia.org/wiki/Delhi_Sultanate" }, { t: "Timurid Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Timurid_Empire" }] },
    { id: "me-ankara", branch: "timurid", y: 1402, when: "1402",
      title: "Timur defeats the Ottomans at Ankara",
      text: "In 1402 Timur defeated the Ottoman army at the Battle of Ankara.",
      imp: 3, link: "ottoman", cites: [{ t: "Timurid Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Timurid_Empire" }] },
    { id: "me-fall-of-constantinople", branch: "ottoman", y: 1453.41, when: "May 29, 1453",
      title: "Ottomans take Constantinople",
      text: "After a siege of nearly two months in which cannon breached the Theodosian walls, Mehmed II captured Constantinople, effectively ending the Roman Empire, and made the city the Ottoman capital in place of Edirne.",
      imp: 1, link: "byzantine", cites: [{ t: "Fall of Constantinople — Wikipedia", u: "https://en.wikipedia.org/wiki/Fall_of_Constantinople" }, { t: "Ottoman Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Ottoman_Empire" }] },
    { id: "me-chaldiran", branch: "ottoman", y: 1514.64, when: "August 23, 1514",
      title: "Battle of Chaldiran",
      text: "Selim I's artillery and Janissaries defeated Shah Ismail I's cavalry; the Ottomans annexed eastern Anatolia, halting Safavid expansion west. Selim had branded Ismail and the Qizilbash heretics.",
      imp: 3, link: "safavid", cites: [{ t: "Battle of Chaldiran — Wikipedia", u: "https://en.wikipedia.org/wiki/Battle_of_Chaldiran" }] },
    { id: "me-siege-vienna-1529", branch: "ottoman", y: 1529, when: "1529",
      title: "Suleiman besieges Vienna",
      text: "Under Suleiman the Magnificent the Ottoman Empire became a global power; he laid siege to Vienna in 1529 but failed to take the city.",
      imp: 3, link: "hre", cites: [{ t: "Ottoman Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Ottoman_Empire" }] },
    { id: "me-lepanto", branch: "ottoman", y: 1571.77, when: "October 7, 1571",
      title: "Battle of Lepanto",
      text: "A papal-organized Holy League fleet led by Spain and Venice under Don John of Austria nearly destroyed the Ottoman fleet in the last major Western battle fought almost entirely by rowing vessels; it was quickly rebuilt.",
      imp: 3, link: "spain", cites: [{ t: "Battle of Lepanto — Wikipedia", u: "https://en.wikipedia.org/wiki/Battle_of_Lepanto" }] },
    { id: "me-vienna-1683", branch: "ottoman", y: 1683.7, when: "September 12, 1683",
      title: "Battle of Vienna",
      text: "Imperial and Polish–Lithuanian forces under John III Sobieski broke Kara Mustafa's siege of Vienna, marking the end of Ottoman expansion into Europe; the Treaty of Karlowitz (1699) gave most of Hungary to the Habsburgs.",
      imp: 2, link: "polish-lithuanian", cites: [{ t: "Battle of Vienna — Wikipedia", u: "https://en.wikipedia.org/wiki/Battle_of_Vienna" }] },
    { id: "me-tenochtitlan-founded", branch: "first-americans", y: 1325, when: "1325 (year Ōme Calli)",
      title: "Mexica found Tenochtitlan",
      text: "The Mexica founded Tenochtitlan on an island in Lake Texcoco in the year Ōme Calli (1325); from 1428 it ruled the Valley of Mexico with Tetzcoco and Tlacopan, allies formalized in 1430 as the Triple Alliance.",
      imp: 2, cites: [{ t: "Aztec Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Aztec_Empire" }] },
    { id: "me-fall-tenochtitlan", branch: "aztec", y: 1521.62, when: "May 26 – August 13, 1521",
      title: "Fall of Tenochtitlan",
      text: "Weakened by a smallpox epidemic from late 1520, Tenochtitlan fell to Hernán Cortés's Spaniards and tens of thousands of Indigenous allies from Tlaxcala and other cities; Cuauhtémoc was captured — a critical stage of Spanish colonization.",
      imp: 1, link: "spain", cites: [{ t: "Fall of Tenochtitlan — Wikipedia", u: "https://en.wikipedia.org/wiki/Fall_of_Tenochtitlan" }] },
    { id: "me-magellan-elcano", branch: "spain", y: 1519.72, end: 1522.68, when: "September 20, 1519 – September 6, 1522",
      title: "Magellan–Elcano circumnavigation",
      text: "The Spanish expedition lost Magellan in battle in the Philippines in April 1521; Elcano brought the Victoria and 18 men home in 1522, the first circumnavigation of the Earth.",
      imp: 2, cites: [{ t: "Magellan expedition — Wikipedia", u: "https://en.wikipedia.org/wiki/Magellan_expedition" }, { t: "Spanish Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Spanish_Empire" }] },
    { id: "me-cajamarca", branch: "inca", y: 1532.88, when: "November 16, 1532",
      title: "Pizarro seizes Atahualpa at Cajamarca",
      text: "A Spanish force of 168 under Francisco Pizarro ambushed and seized the Inca ruler Atahualpa, fresh from civil-war victory over Huáscar; the Spanish executed him on August 29, 1533.",
      imp: 1, link: "spain", cites: [{ t: "Battle of Cajamarca — Wikipedia", u: "https://en.wikipedia.org/wiki/Battle_of_Cajamarca" }, { t: "Inca Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Inca_Empire" }] },
    { id: "me-machu-picchu", branch: "inca", y: 1450, when: "reign of Pachacuti (from 1438)",
      title: "Machu Picchu built",
      text: "Pachacuti, who began the Inca expansion in 1438, is thought to have built Machu Picchu as a family estate or summer retreat.",
      imp: 3, cites: [{ t: "Inca Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Inca_Empire" }] },
    { id: "me-armada", branch: "england", y: 1588.55, when: "1588",
      title: "Defeat of the Spanish Armada",
      text: "Philip II's Armada under the Duke of Medina Sidonia sailed from Lisbon to escort an invasion of Elizabeth I's England; scattered by English fireships off Calais and beaten at Gravelines, it was undone by weather and English gunnery.",
      imp: 2, link: "spain", cites: [{ t: "Spanish Armada — Wikipedia", u: "https://en.wikipedia.org/wiki/Spanish_Armada" }] },
    { id: "me-tupac-amaru", branch: "viceroyalty-peru", y: 1780, end: 1783, when: "1780–1783",
      title: "Rebellion of Túpac Amaru II",
      text: "Túpac Amaru II's rising of 1780 began the largest uprising in Spanish colonial America; it spread across the region and lasted until 1783.",
      imp: 3, cites: [{ t: "Viceroyalty of Peru — Wikipedia", u: "https://en.wikipedia.org/wiki/Viceroyalty_of_Peru" }] },
    { id: "me-ugra-1480", branch: "muscovy", y: 1480.8, when: "October 8 – November 11, 1480",
      title: "Great Stand on the Ugra River",
      text: "Ivan III's Muscovite army and Akhmat Khan's Great Horde faced off across the Ugra; both left after little fighting. Russian historiography treats it as the end of the “Tatar yoke,” though some historians call it insignificant.",
      imp: 3, link: "golden-horde", cites: [{ t: "Great Stand on the Ugra River — Wikipedia", u: "https://en.wikipedia.org/wiki/Great_Stand_on_the_Ugra_River" }, { t: "Grand Duchy of Moscow — Wikipedia", u: "https://en.wikipedia.org/wiki/Grand_Duchy_of_Moscow" }] },
    { id: "me-kongo-portuguese", branch: "kongo", y: 1483, when: "1483–1491",
      title: "Portuguese reach Kongo; its king is baptized",
      text: "Diogo Cão reached the Kongo coast in 1483 and later returned with Catholic priests; in 1491 King Nzinga a Nkuwu was baptized, taking the name João I after Portugal's king.",
      imp: 3, link: "portugal", cites: [{ t: "Kingdom of Kongo — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Kongo" }] },
    { id: "me-benin-portuguese", branch: "benin-kingdom", y: 1485, when: "c. 1485",
      title: "Portuguese traders reach Benin",
      text: "Portuguese under João Afonso de Aveiro were the first Europeans to reach Benin, c. 1485; the Edo traded enslaved people, ivory, pepper and palm oil for manillas and guns, and Rhineland brass fed the Benin Bronzes.",
      imp: 3, link: "portugal", cites: [{ t: "Kingdom of Benin — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Benin" }] },
    { id: "me-afonso-letters", branch: "kongo", y: 1526, when: "1526",
      title: "Afonso I protests to Portugal over the slave trade",
      text: "King Afonso I of Kongo, who from 1509 built a Kongolese church, complained in 1526 to João III of Portugal about Portuguese merchants breaking the royal monopoly on the slave trade.",
      imp: 3, link: "portugal", cites: [{ t: "Kingdom of Kongo — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Kongo" }] },
    { id: "me-adal-war", branch: "ethiopia", y: 1529, end: 1543, when: "1529–1543",
      title: "Ethiopian–Adal war",
      text: "Imam Ahmad ibn Ibrahim al-Ghazi of the Adal Sultanate, aided by Ottoman guns, invaded Ethiopia; 400 Portuguese musketeers under Cristóvão da Gama landed in 1541, and the Imam was killed after Wayna Daga in February 1543.",
      imp: 2, link: "portugal", cites: [{ t: "Ethiopian–Adal war — Wikipedia", u: "https://en.wikipedia.org/wiki/Ethiopian%E2%80%93Adal_war" }] },
    { id: "me-kazan-1552", branch: "tsardom-russia", y: 1552, when: "1552",
      title: "Ivan IV conquers Kazan",
      text: "Ivan IV defeated and annexed the Khanate of Kazan, a Golden Horde successor on the middle Volga, in 1552; Cossacks under Yermak were later hired (1581) to push into western Siberia.",
      imp: 3, link: "golden-horde", cites: [{ t: "Tsardom of Russia — Wikipedia", u: "https://en.wikipedia.org/wiki/Tsardom_of_Russia" }, { t: "Golden Horde — Wikipedia", u: "https://en.wikipedia.org/wiki/Golden_Horde" }] },
    { id: "me-talikota", branch: "vijayanagara", y: 1565, when: "1565",
      title: "Battle of Talikota",
      text: "Allied Deccan sultanates defeated Vijayanagara at Talikota in 1565 and plundered its capital near Hampi, leaving it in ruins; the empire's central power declined thereafter.",
      imp: 3, cites: [{ t: "Vijayanagara Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Vijayanagara_Empire" }] },
    { id: "me-tondibi", branch: "songhai", y: 1591, when: "1591",
      title: "Battle of Tondibi",
      text: "Seeking the trans-Saharan salt and gold trade, Morocco's Saadi sultan Ahmad al-Mansur sent an army under Judar Pasha; its gunpowder weapons routed a far larger Songhai force, and Gao, Timbuktu and Djenné were sacked.",
      imp: 2, cites: [{ t: "Songhai Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Songhai_Empire" }] },
    { id: "me-union-of-crowns", branch: "scotland", y: 1603, when: "1603",
      title: "Union of the Crowns",
      text: "James VI of Scotland's accession as James I of England in 1603 put England, Scotland and Ireland under one monarch while they remained separate states.",
      imp: 3, link: "england", cites: [{ t: "Kingdom of England — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_England" }, { t: "Kingdom of Scotland — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Scotland" }] },
    { id: "me-voc-founded", branch: "dutch-republic", y: 1602.22, when: "March 20, 1602",
      title: "Dutch East India Company founded",
      text: "One of the world's first joint-stock companies, the VOC got a 21-year monopoly on Asian trade, made Batavia (Jakarta) its capital in 1619 and for two centuries ran the only European trading post allowed in Japan.",
      imp: 2, cites: [{ t: "Dutch East India Company — Wikipedia", u: "https://en.wikipedia.org/wiki/Dutch_East_India_Company" }] },
    { id: "me-romanovs", branch: "tsardom-russia", y: 1613, when: "1613",
      title: "Romanovs take the throne",
      text: "After the Time of Troubles (1598–1613), a national assembly chose the boyar Mikhail Romanov as tsar, beginning the Romanov dynasty.",
      imp: 3, cites: [{ t: "Tsardom of Russia — Wikipedia", u: "https://en.wikipedia.org/wiki/Tsardom_of_Russia" }] },
    { id: "me-africans-virginia-1619", branch: "thirteen-colonies", y: 1619, when: "1619",
      title: "First Africans arrive in English Virginia",
      text: "In 1619 an English privateer brought “20 and odd” Africans to Virginia, where they were exchanged for food supplies; slavery later became legal in all thirteen colonies.",
      imp: 2, cites: [{ t: "History & Culture — Historic Jamestowne, National Park Service", u: "https://www.nps.gov/jame/learn/historyculture/index.htm" }, { t: "Thirteen Colonies — Wikipedia", u: "https://en.wikipedia.org/wiki/Thirteen_Colonies" }] },
    { id: "me-tasman-nz", branch: "maori", y: 1642.95, when: "December 1642",
      title: "Abel Tasman's crew reach New Zealand",
      text: "On a VOC voyage, Tasman's ships became the first Europeans to reach New Zealand; Māori in canoes attacked a boat near today's Golden Bay, killing four sailors, and Tasman left.",
      imp: 3, link: "dutch-republic", cites: [{ t: "Abel Tasman — Wikipedia", u: "https://en.wikipedia.org/wiki/Abel_Tasman" }, { t: "Māori people — Wikipedia", u: "https://en.wikipedia.org/wiki/M%C4%81ori_people" }] },
    { id: "me-dutch-recognized", branch: "dutch-republic", y: 1648.08, when: "January 30, 1648",
      title: "Spain recognizes the Dutch Republic",
      text: "Spain and the Dutch Republic made a separate peace at Münster, ending the Eighty Years' War; Spain formally recognized the republic's independence.",
      imp: 3, link: "spain", cites: [{ t: "Peace of Westphalia — Wikipedia", u: "https://en.wikipedia.org/wiki/Peace_of_Westphalia" }, { t: "Dutch Republic — Wikipedia", u: "https://en.wikipedia.org/wiki/Dutch_Republic" }] },
    { id: "me-charles-i-executed", branch: "england", y: 1649, when: "1649",
      title: "Civil war ends with Charles I's execution",
      text: "England's civil war culminated in the execution of Charles I in 1649, and the monarchy was abolished for a time.",
      imp: 2, cites: [{ t: "Kingdom of England — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_England" }] },
    { id: "me-royal-society", branch: "scientific-revolution", y: 1660.9, when: "November 28, 1660 (charter 1662)",
      title: "Royal Society founded",
      text: "A committee announced a college for physico-mathematical experimental learning on November 28, 1660; a royal charter of July 15, 1662, created the Royal Society of London.",
      imp: 3, cites: [{ t: "Scientific Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/Scientific_Revolution" }] },
    { id: "me-harvey", branch: "scientific-revolution", y: 1628, when: "1628",
      title: "Harvey describes the circulation of blood",
      text: "William Harvey's De Motu Cordis (1628) showed that blood circulates through the body rather than being produced in the liver.",
      imp: 3, cites: [{ t: "Scientific Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/Scientific_Revolution" }] },
    { id: "me-principia", branch: "scientific-revolution", y: 1687.51, when: "July 5, 1687",
      title: "Newton's Principia",
      text: "Newton's Principia derived Kepler's laws from universal gravitation; its laws of motion became the foundation of mechanics. It is taken as the culmination of the Scientific Revolution.",
      imp: 1, cites: [{ t: "Scientific Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/Scientific_Revolution" }, { t: "Newton's Philosophiae Naturalis Principia Mathematica — Stanford Encyclopedia of Philosophy", u: "https://plato.stanford.edu/entries/newton-principia/" }] },
    { id: "me-glorious-revolution", branch: "england", y: 1688.85, end: 1689.3, when: "November 1688 – April 1689",
      title: "Glorious Revolution",
      text: "William of Orange landed in Devon on November 5, 1688, and James II fled to France; William and Mary became joint monarchs in 1689. The Revolution formally established constitutional monarchy as the British form of government.",
      imp: 2, link: "dutch-republic", cites: [{ t: "Glorious Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/Glorious_Revolution" }] },
    { id: "me-locke-treatises", branch: "enlightenment", y: 1689, when: "1689",
      title: "Locke's Two Treatises of Government",
      text: "John Locke's Two Treatises of Government appeared in 1689; his ideas on natural rights became central to Enlightenment thought.",
      imp: 3, cites: [{ t: "Age of Enlightenment — Wikipedia", u: "https://en.wikipedia.org/wiki/Age_of_Enlightenment" }] },
    { id: "me-st-petersburg", branch: "tsardom-russia", y: 1703, when: "1703",
      title: "Peter the Great founds St Petersburg",
      text: "In 1703 Peter founded Saint Petersburg on the Neva delta as a new capital and maritime center to replace Moscow.",
      imp: 3, cites: [{ t: "Russian Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Russian_Empire" }] },
    { id: "me-darby-coke", branch: "great-britain", y: 1709, when: "1709",
      title: "Darby smelts iron with coke",
      text: "In 1709 Abraham Darby made progress using coke to fuel his blast furnaces at Coalbrookdale.",
      imp: 3, link: "industrial-revolution", cites: [{ t: "Industrial Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/Industrial_Revolution" }] },
    { id: "me-newcomen", branch: "great-britain", y: 1712, when: "by 1712",
      title: "Newcomen's steam engine",
      text: "Thomas Newcomen introduced the first successful piston steam engine before 1712.",
      imp: 3, link: "industrial-revolution", cites: [{ t: "Industrial Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/Industrial_Revolution" }] },
    { id: "me-encyclopedie", branch: "enlightenment", y: 1751, end: 1772, when: "1751–1772",
      title: "Diderot's Encyclopédie",
      text: "Diderot, d'Alembert and about 150 others compiled the Encyclopédie, a secular, implicitly anti-authoritarian compendium of human knowledge published between 1751 and 1772.",
      imp: 2, cites: [{ t: "Age of Enlightenment — Wikipedia", u: "https://en.wikipedia.org/wiki/Age_of_Enlightenment" }, { t: "Enlightenment — Stanford Encyclopedia of Philosophy", u: "https://plato.stanford.edu/entries/enlightenment/" }] },
    { id: "me-seven-years-war", branch: "great-britain", y: 1756, end: 1763, when: "1756–1763",
      title: "Seven Years' War",
      text: "A global conflict pitting Great Britain and Prussia against France and Austria. France lost its North American possessions, including Canada, and Britain established commercial dominance in India.",
      imp: 2, link: "france", cites: [{ t: "Seven Years' War — Wikipedia", u: "https://en.wikipedia.org/wiki/Seven_Years%27_War" }] },
    { id: "me-plassey", branch: "great-britain", y: 1757.48, when: "June 23, 1757",
      title: "Battle of Plassey",
      text: "Robert Clive's East India Company army defeated Siraj-ud-Daulah, last independent Nawab of Bengal, and his French allies; Bengal, once the Mughal Empire's largest province, fell under Company control.",
      imp: 2, link: "mughal", cites: [{ t: "Battle of Plassey — Wikipedia", u: "https://en.wikipedia.org/wiki/Battle_of_Plassey" }, { t: "Mughal Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Mughal_Empire" }] },
    { id: "me-spinning-jenny", branch: "industrial-revolution", y: 1764, when: "1764",
      title: "Hargreaves' spinning jenny",
      text: "In 1764 in Oswaldtwistle, Lancashire, James Hargreaves invented the spinning jenny; Richard Arkwright patented the water frame in 1769.",
      imp: 3, cites: [{ t: "Industrial Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/Industrial_Revolution" }] },
    { id: "me-cook-nz", branch: "maori", y: 1769.76, when: "October 6, 1769",
      title: "Cook's Endeavour reaches New Zealand",
      text: "Cook's Royal Navy–Royal Society expedition landed at Poverty Bay; early encounters left several Māori dead. Tahitian navigator Tupaia interpreted, and the crew charted both main islands over six months.",
      imp: 2, link: "great-britain", cites: [{ t: "First voyage of James Cook — Wikipedia", u: "https://en.wikipedia.org/wiki/First_voyage_of_James_Cook" }, { t: "Māori people — Wikipedia", u: "https://en.wikipedia.org/wiki/M%C4%81ori_people" }] },
    { id: "me-cook-botany-bay", branch: "first-australians", y: 1770.33, when: "April 29, 1770",
      title: "Cook lands at Botany Bay",
      text: "Cook's party were the first known Europeans to reach Australia's east coast; landing at Botany Bay, they had a brief, tense encounter with Aboriginal men.",
      imp: 3, link: "great-britain", cites: [{ t: "First voyage of James Cook — Wikipedia", u: "https://en.wikipedia.org/wiki/First_voyage_of_James_Cook" }] },
    { id: "me-partitions-poland", branch: "polish-lithuanian", y: 1772, end: 1795, when: "1772, 1793, 1795",
      title: "Partitions of Poland–Lithuania",
      text: "Russia, Prussia and Austria partitioned the Commonwealth in three stages; despite its May 3, 1791, constitution, it was erased from the map by 1795, with Russia taking most of its land and people.",
      imp: 2, link: "russian-empire", cites: [{ t: "Polish–Lithuanian Commonwealth — Wikipedia", u: "https://en.wikipedia.org/wiki/Polish%E2%80%93Lithuanian_Commonwealth" }, { t: "Russian Empire — Wikipedia", u: "https://en.wikipedia.org/wiki/Russian_Empire" }] },
    { id: "me-treaty-of-paris-1783", branch: "usa", y: 1783.67, when: "September 3, 1783",
      title: "Treaty of Paris ends the Revolutionary War",
      text: "After preliminary articles of November 30, 1782, in which Britain accepted American independence and boundaries, the formal peace was signed in Paris on September 3, 1783.",
      imp: 2, link: "great-britain", cites: [{ t: "Treaty of Paris, 1783 — Office of the Historian, U.S. Department of State", u: "https://history.state.gov/milestones/1776-1783/treaty" }] },
    { id: "me-us-constitution", branch: "usa", y: 1787.71, when: "signed September 17, 1787; in effect March 4, 1789",
      title: "US Constitution signed",
      text: "Delegates to the Constitutional Convention signed the Constitution in Philadelphia; it was ratified in 1788, took effect in 1789, and is the oldest written national constitution still in force. The Bill of Rights followed in 1791.",
      imp: 2, cites: [{ t: "Constitution of the United States — Wikipedia", u: "https://en.wikipedia.org/wiki/Constitution_of_the_United_States" }] },
    { id: "me-bastille", branch: "france", y: 1789.54, when: "July 14, 1789",
      title: "French Revolution: the Bastille falls",
      text: "With the Estates General convened in May 1789, the storming of the Bastille on July 14 drove the Assembly to abolish feudalism; the Declaration of the Rights of Man and of the Citizen followed on August 26.",
      imp: 1, cites: [{ t: "French Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/French_Revolution" }] },
    { id: "me-haitian-revolution", branch: "france", y: 1791.64, when: "August 21, 1791",
      title: "Haitian Revolution begins",
      text: "A slave revolt in the French colony of Saint-Domingue began a revolution, led most prominently by Toussaint Louverture, that ended in independence on January 1, 1804 — one of the only slave rebellions known to have founded a state.",
      imp: 1, cites: [{ t: "Haitian Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/Haitian_Revolution" }] },
    { id: "me-first-republic", branch: "france", y: 1792.72, when: "September 1792 – January 1793",
      title: "Monarchy abolished; Louis XVI executed",
      text: "The French First Republic replaced the monarchy in September 1792 and Louis XVI was executed in January 1793; some 16,000 people were then executed in the Reign of Terror, which ended in July 1794.",
      imp: 2, cites: [{ t: "French Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/French_Revolution" }] },
    { id: "me-brumaire", branch: "france", y: 1799.86, when: "1799 (18 Brumaire)",
      title: "Napoleon's coup of 18 Brumaire",
      text: "The coup of 18 Brumaire in 1799 ended the revolutionary government's instability and set up the Consulate, with Napoleon Bonaparte as First Consul.",
      imp: 3, cites: [{ t: "French Revolution — Wikipedia", u: "https://en.wikipedia.org/wiki/French_Revolution" }] },
    { id: "me-arab-conquests", branch: "rashidun", y: 634, end: 651, when: "634–651",
      title: "Arab conquest of Persia and Byzantine lands",
      text: "Under Caliph Umar (634–644) the caliphate took over two-thirds of the Byzantine Empire and nearly all of the Sasanian Empire; Egypt fell by 642, and the conquest of Persia was completed under Uthman in 651.",
      imp: 1, link: "sasanian", cites: [{ t: "Rashidun Caliphate — Wikipedia", u: "https://en.wikipedia.org/wiki/Rashidun_Caliphate" }] },
    { id: "me-karbala", branch: "islam", y: 680.78, when: "October 10, 680 (10 Muharram 61 AH)",
      title: "Battle of Karbala: Husayn killed",
      text: "Forces of the Umayyad caliph Yazid I killed Muhammad's grandson Husayn ibn Ali and most of his family. Commemorated each Ashura, it helped consolidate the pro-Alid movement into a separate sect — Shi'ism.",
      imp: 2, link: "umayyad", cites: [{ t: "Battle of Karbala — Wikipedia", u: "https://en.wikipedia.org/wiki/Battle_of_Karbala" }] },
    { id: "me-maya-collapse", branch: "maya", y: 750, end: 900, when: "8th–9th centuries",
      title: "Classic Maya collapse",
      text: "Southern lowland Maya cities declined in the 8th and 9th centuries and were then abandoned, while Chichen Itza and other northern Yucatán centers continued. Drought is the leading explanation, but no theory is universally accepted.",
      imp: 2, cites: [{ t: "Classic Maya collapse — Wikipedia", u: "https://en.wikipedia.org/wiki/Classic_Maya_collapse" }] },
    { id: "me-lanse-aux-meadows", branch: "vikings", y: 1021, when: "1021",
      title: "Norse in Newfoundland (L'Anse aux Meadows)",
      text: "Tree-ring dating places Norse activity at L'Anse aux Meadows, Newfoundland, in 1021 — the only confirmed Norse site in North America outside Greenland, possibly a Vinland settlement of the sagas.",
      imp: 2, link: "first-americans", cites: [{ t: "L'Anse aux Meadows — Wikipedia", u: "https://en.wikipedia.org/wiki/L%27Anse_aux_Meadows" }] },
    { id: "me-cahokia", branch: "first-americans", y: 1050, end: 1350, when: "c. 1050 – abandoned by 1350",
      title: "Cahokia, Mississippian city",
      text: "Across the Mississippi from present-day St. Louis, Cahokia grew from about 1050 and held perhaps 15,000–20,000 people around 1100; Monks Mound is the largest earthen mound north of Mexico. The city was abandoned by 1350.",
      imp: 2, cites: [{ t: "Cahokia — Wikipedia", u: "https://en.wikipedia.org/wiki/Cahokia" }] },
    { id: "me-ghazan-islam", branch: "ilkhanate", y: 1295, when: "1295",
      title: "Ilkhan Ghazan converts to Islam",
      text: "Later Ilkhanid rulers, beginning with Ghazan in 1295, converted to Islam.",
      imp: 3, link: "islam", cites: [{ t: "Ilkhanate — Wikipedia", u: "https://en.wikipedia.org/wiki/Ilkhanate" }] },
    { id: "me-zimbabwe-gold", branch: "great-zimbabwe", y: 1300, when: "c. 1300",
      title: "Great Zimbabwe dominates the gold trade",
      text: "Around 1300 Great Zimbabwe became the interior's leading trading center, exporting gold via Swahili city-states into the Indian Ocean trade; Persian bowls and Chinese celadon have been found there.",
      imp: 3, cites: [{ t: "Kingdom of Zimbabwe — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_Zimbabwe" }] },
    { id: "me-hundred-years-war", branch: "france", y: 1337, end: 1453, when: "1337–1453",
      title: "Hundred Years' War",
      text: "Conflicts between England and France sparked by Edward III's claim to the French crown. Helped by Joan of Arc's boost to French morale, France won; England lost all its continental lands except Calais.",
      imp: 2, link: "england", cites: [{ t: "Hundred Years' War — Wikipedia", u: "https://en.wikipedia.org/wiki/Hundred_Years%27_War" }] },
    { id: "me-english-reformation", branch: "england", y: 1534, when: "1530s",
      title: "Henry VIII breaks with Rome",
      text: "After Pope Clement VII refused to annul his marriage to Catherine of Aragon, Henry VIII had the Reformation Parliament (1529–1536) abolish papal authority; the Act of Supremacy made him Supreme Head of the Church of England.",
      imp: 2, link: "catholicism", cites: [{ t: "English Reformation — Wikipedia", u: "https://en.wikipedia.org/wiki/English_Reformation" }, { t: "Kingdom of England — Wikipedia", u: "https://en.wikipedia.org/wiki/Kingdom_of_England" }] },
  ],
});
